{
    int n;

    if (scanf("%d", &n) != 1)
        return 0;

    print_bar(20);
    printf("sum = %d\n", sum_to(n));
    print_bar(20);

    return 0;
}

/* 返回 1 + 2 + ... + n 的和 */
int sum_to(int n)
{
    int i, s = 0;

    for (i = 1; i <= n; i++)
        s += i;

    return s;
}

/* 在一行内输出 len 个 '-'，没有返回值 */
void print_bar(int len)
{
    int i;

    for (i = 0; i < len; i++)
        putchar('-');
    putchar('\n');
}

