#define MAXN 1000

void swap(int *p, int *q);
void sort_desc(int a[], int n);
void print_array(const int a[], int n);

int main(void)
{
    int n, i, a[MAXN];

    if (scanf("%d", &n) != 1 || n < 1 || n > MAXN)
        return 0;
    for (i = 0; i < n; i++)
        if (scanf("%d", &a[i]) != 1)
            return 0;

    sort_desc(a, n);
    print_array(a, n);
    return 0;
}

/* 通过指针交换调用方的两个变量 */
void swap(int *p, int *q)
{
    int t = *p;
    *p = *q;
    *q = t;
}

/* 选择排序：每轮把未排序区间的最大元素换到区间首部 */
void sort_desc(int a[], int n)
{
    int i, j, k;

    for (i = 0; i < n - 1; i++) {
        k = i;
        for (j = i + 1; j < n; j++)
            if (a[j] > a[k])
                k = j;
        if (k != i)
            swap(&a[i], &a[k]);
    }
}

void print_array(const int a[], int n)
{
    int i;

    for (i = 0; i < n; i++) {
        if (i > 0)
            putchar(' ');
        printf("%d", a[i]);
    }
    putchar('\n');
}

