#include <stdio.h>

int gcd(int a, int b);
void reduce(int a, int b, int *p, int *q);

int main(void)
{
    int a, b, p, q;

    if (scanf("%d %d", &a, &b) != 2 || a <= 0 || b <= 0)
        return 0;

    reduce(a, b, &p, &q);
    printf("%d/%d\n", p, q);
    return 0;
}

/* 辗转相除法求最大公约数 */
int gcd(int a, int b)
{
    int t;

    while (b != 0) {
        t = a % b;
        a = b;
        b = t;
    }
    return a;
}

/* 约分，结果通过指针 p、q 带回调用处 */
void reduce(int a, int b, int *p, int *q)
{
    int g = gcd(a, b);

    *p = a / g;
    *q = b / g;
}

