long long fact(int n);
long long comb(int n, int k);

int main(void)
{
    int n, k;

    if (scanf("%d %d", &n, &k) != 2 || n < 0 || k < 0 || k > n || n > 20)
        return 0;

    printf("%lld\n", comb(n, k));
    return 0;
}

/* 返回 n!，n <= 20 时 20! 仍在 long long 范围内 */
long long fact(int n)
{
    long long r = 1;
    int i;

    for (i = 2; i <= n; i++)
        r *= i;
    return r;
}

/* 组合数：在函数内部调用 fact，体现嵌套调用 */
long long comb(int n, int k)
{
    return fact(n) / (fact(k) * fact(n - k));
}

