#include <stdio.h>

double power(double x, int e);
double factorial(int m);
double exp_taylor(double x, int n);

int main(void)
{
    double x, s;
    int n;

    if (scanf("%lf %d", &x, &n) != 2 || n < 1 || n > 12)
        return 0;

    s = exp_taylor(x, n);
    printf("%.4f\n", s);
    return 0;
}

/* x 的 e 次方，用循环连乘，e = 0 时返回 1 */
double power(double x, int e)
{
    double r = 1.0;
    int i;

    for (i = 0; i < e; i++)
        r *= x;
    return r;
}

/* m 的阶乘，用 double 保存以避免整数溢出 */
double factorial(int m)
{
    double r = 1.0;
    int i;

    for (i = 2; i <= m; i++)
        r *= i;
    return r;
}

/* 前 n 项之和：i 从 0 到 n-1，每项调用 power 与 factorial */
double exp_taylor(double x, int n)
{
    double s = 0.0;
    int i;

    for (i = 0; i < n; i++)
        s += power(x, i) / factorial(i);
    return s;
}

