int add(int a, int b);
int sub(int a, int b);
int mul(int a, int b);
int divide(int a, int b, double *result);

int main(void)
{
    int op, a, b;
    double r;

    if (scanf("%d %d %d", &op, &a, &b) != 3)
        return 0;

    switch (op) {
    case 1:
        printf("%d\n", add(a, b));
        break;
    case 2:
        printf("%d\n", sub(a, b));
        break;
    case 3:
        printf("%d\n", mul(a, b));
        break;
    case 4:
        if (divide(a, b, &r))
            printf("%.2f\n", r);
        else
            printf("error: divide by zero\n");
        break;
    default:
        printf("error: unknown operator\n");
        break;
    }

    return 0;
}

int add(int a, int b)
{
    return a + b;
}

int sub(int a, int b)
{
    return a - b;
}

int mul(int a, int b)
{
    return a * b;
}

/* 成功返回 1 并通过指针带回商；除数为 0 返回 0 */
int divide(int a, int b, double *result)
{
    if (b == 0)
        return 0;
    *result = (double)a / b;
    return 1;
}

