    int n, a[MAXN];

    if (scanf("%d", &n) != 1 || n < 1 || n > MAXN)
        return 0;

    read_array(a, n);
    printf("sum=%lld\n", sum_array(a, n));
    printf("max_index=%d\n", index_of_max(a, n));
    printf("above=%d\n", count_above_average(a, n));
    return 0;
}

void read_array(int a[], int n)
{
    int i;

    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);
}

long long sum_array(const int a[], int n)
{
    int i;
    long long total = 0;

    for (i = 0; i < n; i++)
        total += a[i];
    return total;
}

int index_of_max(const int a[], int n)
{
    int i, idx = 0;

    for (i = 1; i < n; i++)
        if (a[i] > a[idx])
            idx = i;
    return idx;
}

int count_above_average(const int a[], int n)
{
    double average = (double)sum_array(a, n) / n;
    int i, cnt = 0;

    for (i = 0; i < n; i++)
        if (a[i] > average)
            cnt++;
    return cnt;
}

