/* 数值 0~15 映射为大写十六进制字符 */
char digit_char(int d)
{
    if (d < 10)
        return (char)('0' + d);
    return (char)('A' + d - 10);
}

/* 把 n 写成 base 进制字符串，存进调用方提供的 out 缓冲区 */
void to_base(long long n, int base, char *out)
{
    int len = 0, i;

    if (n == 0) {
        out[0] = '0';
        out[1] = '\0';
        return;
    }

    while (n > 0) {
        out[len++] = digit_char((int)(n % base));
        n /= base;
    }
    out[len] = '\0';

    /* 此时 out 中是低位在前的逆序串，首尾对调后得到正确顺序 */
    for (i = 0; i < len / 2; i++) {
        char t = out[i];
        out[i] = out[len - 1 - i];
        out[len - 1 - i] = t;
    }
}

